def paper(title,authors,year,venue,source,url,doi,topic,abstract,category,**extra):
    x=dict(title=title,titleZh="Not displayed",authors=authors,year=year,venue=venue,source=source,category=category,
      evidence="Publisher or authoritative index record verified",takeaway=abstract,theory="See the linked article.",data="See the linked article.",method="See the linked article.",results=abstract,
      relevance="Selected under the strict relevance hierarchy; adjacent evidence is explicitly labeled.",limitations="See the linked source for design-specific limitations.",url=url,doi=doi,topicIds=[topic],
      abstractMode="summary",originalAbstract="",abstractUnavailableReason="Verbatim republication permission was not confirmed; this is an English summary based on the publisher or repository abstract.",abstractEn=abstract,abstractSource=url,
      readingPriority="normal",priorityReason="Direct or explicitly labeled adjacent evidence.",readingUse="Compact evidence briefing.",researchConnection="Relevant to the named research idea.",publicationType="journal",peerReviewed=True,publicationStatus="published")
    x.update(extra); return x

def formal(*args,tier,edition,quartile,reason="",**kw):
    return paper(*args,journalEdition=edition,jifQuartile=quartile,indexSource="Web of Science Core Collection",tierNote=f"{tier}. {reason}".strip(),**kw)

dissertation=[
 formal("The influence of transportation, social norms, cultural identity, and affective disposition in transnational media enjoyment","S. B. Lee and colleagues",2024,"Frontiers in Psychology, 15, 1377898","Frontiers","https://doi.org/10.3389/fpsyg.2024.1377898","https://doi.org/10.3389/fpsyg.2024.1377898","culture","A survey of Malaysian viewers of foreign television drama models how narrative transportation, perceived social norms, cultural identity, and affective disposition jointly predict enjoyment. The study distinguishes cultural recognition from immersion and character-related affect, showing that reception of culturally foreign narratives depends on both audience identity and narrative experience. It is directly useful for separating understanding, identification, and evaluative response in transnational reception.","Dissertation · transnational reception",tier="Primary tier: SSCI/SCIE JCR Q1/Q2",edition="SSCI/SCIE",quartile="JCR Q2"),
 formal("Cultural distance perceived by Chinese audiences in the Korean film Silenced: a study of cross-cultural receptions in film content elements","Xiaoyu Gao, Mahyuddin Ahmad Hamedi, and Chenyang Wang",2024,"Frontiers in Communication, 9, 1306309","Frontiers","https://doi.org/10.3389/fcomm.2024.1306309","https://doi.org/10.3389/fcomm.2024.1306309","culture","This reception study examines how Chinese audiences interpret culturally distant elements in the Korean film Silenced. It identifies multiple content-level sources of distance rather than treating culture as a single national score, and relates audience interpretation to social-darkness themes and cultural discount. The article is a direct reception study but concerns a Korean film rather than Chinese mythology.","Dissertation · direct reception, adjacent object",tier="Downgrade tier 3: ESCI",edition="ESCI",quartile="Not assigned as JCR Q1-Q4",reason="No second unrecommended SSCI/SCIE Q1-Q2 article met the same direct reception threshold today.")]

ishow=[
 formal("Cultivating the Imagination of China and the Western World: Foreign Influencers on Chinese Digital Platforms","Zheng Li, Jie Su, and Xin Su",2025,"SAGE Open","SAGE Journals","https://doi.org/10.1177/21582440251395862","https://doi.org/10.1177/21582440251395862","ishow-speed","The study examines how foreign social-media influencers on Chinese platforms mediate intercultural understanding through political, cultural, and commercial filters. Audience-centered qualitative evidence shows that foreign creators can provide an outsider perspective on China and an insider perspective on other societies, while their influence remains shaped by platform and policy conditions. This is direct foreign-influencer evidence, although it studies Chinese audiences rather than overseas followers of a China visit.","甲亢哥访华 · direct foreign-influencer evidence",tier="Primary tier: SSCI JCR Q1/Q2",edition="SSCI",quartile="JCR Q1"),
 formal("Is an exciting outsider or a trustworthy local more persuasive? A self-construal contingent, dual-pathway model of cross-cultural travel vlogs","Authors listed on publisher record",2026,"Journal of China Tourism Research, OnlineFirst","Taylor & Francis","https://doi.org/10.1080/19388160.2026.2652631","https://doi.org/10.1080/19388160.2026.2652631","ishow-speed","Using the context of inbound travel to China, the study compares foreign outsider and local insider vlog perspectives and tests how linguistic arousal and audience self-construal shape persuasion. It separates an excitement pathway from a trust pathway to travel intention, demonstrating that a foreign creator is not uniformly more persuasive than a local one. This is a close mechanism study for IShowSpeed-style China travel content rather than a study of IShowSpeed himself.","甲亢哥访华 · adjacent China-travel mechanism",tier="Primary tier: SSCI JCR Q1/Q2",edition="SSCI",quartile="JCR Q1")]

xtrans=[
 formal("Language Justice and Machine Translation on Social Media","Authors listed on publisher record",2026,"Modern Languages Open","Liverpool University Press","https://doi.org/10.3828/mlo.v0i0.466","https://doi.org/10.3828/mlo.v0i0.466","x-translation","This article analyzes the language-justice consequences of machine-translation systems embedded in social media. It explains how automatic translation can widen cross-language access while also exposing code-switched or community-bounded speech to unintended audiences, distorting identity-sensitive language, and creating moderation or reputational harms. The evidence is directly about platform translation, including Twitter examples, but it is a critical analysis rather than a causal test of replies or sharing.","X automatic translation · direct platform mechanism",tier="Downgrade tier 4: other peer-reviewed journal",edition="Other peer-reviewed",quartile="No verified JCR quartile",reason="No unrecommended SSCI/SCIE or ESCI study directly testing X built-in translation and interaction outcomes was verified today."),
 formal("The role of AI in international communication: Cross-cultural implications of automated translation and content curation","Can Zhu",2025,"Convergence, OnlineFirst","SAGE Journals","https://doi.org/10.1177/13548565251403582","https://doi.org/10.1177/13548565251403582","x-translation","A survey of 300 participants examines automated translation and content curation in international communication. The results indicate that AI can facilitate cross-cultural interaction, while accuracy, cultural relevance, representation, inclusion, and bias constrain those benefits. This is an adjacent platform-level study because it is not specific to X and does not isolate reply, repost, or relationship-formation behavior.","X automatic translation · adjacent cross-platform evidence",tier="Primary tier: SSCI JCR Q1/Q2",edition="SSCI",quartile="JCR Q1")]

ai=[
 formal("Generative AI and employee well-being: Exploring the emotional, social, and cognitive impacts of adoption","Authors listed on publisher record",2026,"Journal of Innovation & Knowledge, 11, 100844","Elsevier","https://doi.org/10.1016/j.jik.2025.100844","https://doi.org/10.1016/j.jik.2025.100844","ai-wellbeing","Survey data from about 130 knowledge workers are analyzed with partial least squares structural equation modeling to test how attitudes toward generative AI predict adoption intensity and emotional, social, and cognitive well-being. Positive attitudes increase adoption, and the extent of adoption is associated with all three well-being dimensions, with team cohesion operating as an important pathway. The cross-sectional design limits causal inference.","Workplace AI and well-being · direct evidence",tier="Primary tier: SSCI JCR Q1/Q2",edition="SSCI",quartile="JCR Q1"),
 formal("Would you rather work with ChatGPT or a human coworker? Exploring the impact of generative AI on job satisfaction","Dominik Zahs and Lynn Schmodde",2026,"Review of Managerial Science, OnlineFirst","Springer Nature","https://doi.org/10.1007/s11846-026-01004-1","https://doi.org/10.1007/s11846-026-01004-1","ai-wellbeing","A two-stage vignette experiment places participants in a time-pressured corporate communication task and compares task support from ChatGPT with support from a human coworker. ChatGPT support produces lower job satisfaction through reduced perceived organizational support and opportunity to perform and increased job insecurity. The comparison identifies social, motivational, and work-context pathways through which generative AI can reduce workplace well-being.","Workplace AI and well-being · direct evidence",tier="Primary tier: SSCI JCR Q1/Q2",edition="SSCI",quartile="JCR Q1")]

preprints=[
 paper("Cultural Attraction and Cultural Discount: Mechanisms Influencing Chinese Film Export Box Office","Liu Xiaojuan, Shao Yang, and Wu Zeyu",2026,"SSRN working paper","SSRN","https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7305971","https://doi.org/10.2139/ssrn.7305971","culture","Panel data from 37 countries for 2016–2024 are used to model a nonlinear relationship between cultural distance and overseas box-office performance of Chinese films. The paper distinguishes a novelty-driven cultural-attraction path from a value-resonance identification path and tests power distance and cultural clusters as boundary conditions. It is closely aligned with the dissertation’s value-fit and cultural-boundary questions, but it has not completed journal peer review.","Preprint · dissertation · not peer reviewed",publicationType="preprint",peerReviewed=False,publicationStatus="preprint",publicationDate="2026-08-18 (first posted)"),
 paper("Foreign influencer operations: How TikTok shapes American perceptions of China","Authors listed on arXiv record",2026,"arXiv:2601.14118","arXiv","https://arxiv.org/abs/2601.14118","arXiv:2601.14118","ishow-speed","This preprint studies foreign-influencer content about China on TikTok and its relationship to American perceptions of China. It treats influencer narratives as platform-mediated persuasion and examines how creator identity and content circulation can shape country image. It is directly relevant to the IShowSpeed idea, but its claims remain working-paper evidence pending journal peer review.","Preprint · IShowSpeed idea · not peer reviewed",publicationType="preprint",peerReviewed=False,publicationStatus="preprint",publicationDate="2026-01-24 (arXiv record)"),
 paper("Platform-Mediated Accommodation and Identity Construction among ‘TikTok Refugees’ on Chinese Social Media","Authors listed on SSRN record",2026,"SSRN working paper 6464201","SSRN","https://papers.ssrn.com/sol3/papers.cfm?abstract_id=6464201","https://doi.org/10.2139/ssrn.6464201","x-translation","This working paper examines cross-language accommodation, code-mixing, and multimodal translingual practice among foreign users who moved to RedNote. It argues that accommodation is shaped by algorithmic visibility and platform norms rather than simple linguistic convergence. This is a high-relevance adjacent preprint for cross-language platform interaction, not a direct test of X automatic translation, and it has not completed journal peer review.","Preprint · X translation adjacent mechanism · not peer reviewed",publicationType="preprint",peerReviewed=False,publicationStatus="preprint",publicationDate="2026-03-24 (first posted)"),
 paper("Beyond Performance: Replacing a Human Coworker with AI Enhances Motivation","Brice Corgnet, Elena Fumagalli, and Sarah Rezaei",2026,"SSRN working paper 6924498","SSRN","https://papers.ssrn.com/sol3/papers.cfm?abstract_id=6924498","https://doi.org/10.2139/ssrn.6924498","ai-wellbeing","In a preregistered experiment with 1,091 participants, people completed a creative task either with another human or with generative AI under matched conditions. Collaborating with AI increased perceived relatedness, competence, autonomy, job satisfaction, and interest, with reported standardized differences of roughly 0.2–0.5. The findings provide a positive counterpoint to workplace-AI strain accounts but have not completed journal peer review.","Preprint · workplace AI and well-being · not peer reviewed",publicationType="preprint",peerReviewed=False,publicationStatus="preprint",publicationDate="2026-06-24 (first posted)")]

joc=[
("Softening the spring: Sensitization of transient media effects through repeated exposure over time","10.1093/joc/jqag024","Repeated-exposure data are used to test whether initially transient media effects become stronger as audiences encounter similar messages over time. The study develops a sensitization account and estimates how the timing and accumulation of exposure alter effect persistence rather than assuming a constant one-shot response."),
("The integrative theory of supportive network (re)structuring: a case study in the context of LGBTQ+ hate speech","10.1093/joc/jqag023","The article develops and applies an integrative theory of how people reorganize supportive communication networks after exposure to LGBTQ+ hate speech. It links harmful communication, support seeking, network activation, and relationship change to explain how social resources are mobilized and restructured."),
("When it’s your own child: effects of media narratives on U.S. parents’ support for their LGBTQ+ teen","10.1093/joc/jqag021","An experiment tests how media narratives influence U.S. parents’ responses to the prospect of having an LGBTQ+ teenager. The design examines whether perspective-taking and identification with a parent-centered narrative increase supportive attitudes and intended behavior."),
("Positioning enjoyment and appreciation as key components of news use","10.1093/joc/jqag020","The study argues that news use should be understood partly through the distinct experiences of enjoyment and appreciation. Survey and measurement evidence separates pleasurable engagement from meaningful or reflective responses and relates both to patterns of news consumption."),
("Academic freedom: defending a public good","10.1093/joc/jqag017","This oration frames academic freedom as a public good that supports knowledge production and democratic communication. It identifies institutional and political pressures on scholarly inquiry and argues for collective rather than purely individual defenses."),
("Inoculating against fatalistic beliefs: a comparative test of narrative and non-narrative strategies","10.1093/joc/jqag018","A comparative experiment tests narrative and non-narrative inoculation messages designed to reduce fatalistic beliefs. The study evaluates whether story form changes resistance, perceived threat, counterarguing, and later belief outcomes."),
("Rejection of cross-cutting news depends on content, sources, and cultural contexts: evidence from online trace data","10.1093/joc/jqag014","Online trace data across cultural settings are used to examine when audiences reject politically cross-cutting news. The results show that avoidance cannot be reduced to ideological disagreement alone because content, source cues, and national context jointly shape exposure and rejection."),
("Loneliness and the local news environment","10.1093/joc/jqag016","The article connects individual loneliness with characteristics of local news environments. It tests whether access to and engagement with community information correspond to social connectedness while accounting for individual and contextual differences."),
("Looking good, fitting in: co-trajectories of appearance- and friendship-related identity distress and positive online self-presentation in adolescence","10.1093/joc/jqag015","Longitudinal data trace how appearance-related and friendship-related identity distress develop alongside positive online self-presentation during adolescence. The study identifies linked trajectories and clarifies which patterns of self-presentation coincide with greater or lower identity strain."),
("Do good chat groups make good neighbors? Continuity and change of norms in neighbor relations under digital co-presence","10.1093/joc/jqag013","The study examines neighborhood chat groups as spaces of digital co-presence. It shows how existing norms of neighborliness persist, shift, or become contested when coordination, support, surveillance, and conflict are moved into persistent group communication.")]
